<?php if(!isset($usuario,$modulo,$detalle)||($usuario['rol']??'')!=='ADMIN'){http_response_code(403);exit;} $r=$detalle;
$campos=match($modulo){'usuarios'=>['usuario'=>'Nombre de usuario','rol'=>'Rol','nombres'=>'Cliente','cedula'=>'Cédula','estado'=>'Estado','bloqueado'=>'Bloqueo','intentos_fallidos'=>'Intentos fallidos'],'cuentas'=>['numero'=>'Número','nombres'=>'Cliente','cedula'=>'Cédula','tipo'=>'Tipo','saldo'=>'Saldo','estado'=>'Estado'],'tarjetas'=>['codigo_qr'=>'Código QR','numero_cuenta'=>'Cuenta','nombres'=>'Cliente','cedula'=>'Cédula','activa'=>'Estado de tarjeta','cuenta_activa'=>'Estado de cuenta','fecha_emision'=>'Emisión','fecha_anulacion'=>'Anulación'],'movimientos'=>['id'=>'Identificador','nombres'=>'Cliente','cedula'=>'Cédula','numero_cuenta'=>'Cuenta','tipo'=>'Tipo','monto'=>'Monto','fecha'=>'Fecha','cuenta_relacionada'=>'Cuenta relacionada','saldo_resultante'=>'Saldo resultante','referencia'=>'Referencia']};?>
<section class="crud-detalle-seccion"><h2>Detalle del registro</h2><dl class="crud-detalle-grid"><?php foreach($campos as $k=>$label):?><div class="crud-detalle-campo"><dt><?=h($label)?></dt><dd><?php if(in_array($k,['estado','activa','cuenta_activa'],true)):?><?=estado($r[$k])?><?php elseif($k==='bloqueado'):?><?=estado(!$r[$k],'No bloqueado','Bloqueado')?><?php elseif(in_array($k,['saldo','monto','saldo_resultante'],true)):?><?=dinero($r[$k])?><?php else:?><?=h($r[$k]??'—')?><?php endif;?></dd></div><?php endforeach;?></dl></section>
<?php if($modulo==='usuarios'):?>
<section class="crud-detalle-seccion"><h2>Gestión de acceso</h2><?php if($r['rol']==='ADMIN'):?><div class="alerta alerta-info">Administrador protegido. No se permiten modificaciones desde este módulo.</div><?php else:?>
<div class="crud-acciones"><?php accion($r['estado']?'desactivar':'activar',$r['estado']?'Desactivar':'Reactivar',['id'=>$r['id']]);if($r['bloqueado']||$r['intentos_fallidos'])accion('desbloquear','Desbloquear',['id'=>$r['id']]);?></div></section>
<section class="crud-formulario-contenedor"><h2>Restablecer PIN</h2><p>Reinicia los intentos fallidos y desbloquea el acceso, sin cambiar el estado activo/inactivo.</p><form method="post" action="<?=h($ruta)?>" class="crud-formulario" onsubmit="return confirm('¿Restablecer el PIN?')"><?=token()?><input type="hidden" name="accion" value="pin"><input type="hidden" name="id" value="<?=h($r['id'])?>"><?php require __DIR__.'/modulo-pin.php';?><button type="submit" class="btn btn-primario">Restablecer PIN</button></form><?php endif;?></section>
<?php elseif($modulo==='cuentas'):?><section class="crud-detalle-seccion"><h2>Gestión de cuenta</h2><p>Solo puede cambiarse el estado. La reactivación emite un QR nuevo. La eliminación requiere saldo cero y ausencia de movimientos propios o relacionados.</p><div class="crud-acciones"><?php accion($r['estado']?'desactivar':'activar',$r['estado']?'Desactivar':'Reactivar',['numero'=>$r['numero']]);accion('eliminar','Eliminar cuenta',['numero'=>$r['numero']]);?></div></section>
<?php elseif($modulo==='tarjetas'):?><section class="crud-detalle-seccion"><h2>Imagen QR</h2><?php if(!$r['activa']):?><div class="alerta alerta-info">Tarjeta histórica inactiva. No debe utilizarse para operaciones.</div><?php endif;?><img class="crud-qr" src="<?=enlace(['vista'=>'qr','id'=>$r['codigo_qr']])?>" alt="Código QR de la tarjeta <?=h($r['codigo_qr'])?>" width="232" height="232"><p><a class="btn btn-primario" href="<?=enlace(['vista'=>'descargar','id'=>$r['codigo_qr']])?>">Descargar PNG</a></p></section><?php endif;?>
